/**
 * Create a deterministic, entirely fictional T20 corpus for local performance
 * measurements.  The files use the Cricsheet JSON shape so the normal importer
 * exercises the same database path as a source dataset.
 *
 * Usage: node scripts/generate-representative-corpus.mjs [--fixtures 300] [--output data/performance/representative-t20]
 */
import { mkdir, readdir, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';

const DEFAULT_FIXTURES = 300;
const DELIVERIES_PER_FIXTURE = 240;

function argument(name, fallback) {
  const index = process.argv.indexOf(name);
  return index === -1 ? fallback : (process.argv[index + 1] ?? fallback);
}

function positiveInteger(value, name) {
  const parsed = Number(value);
  if (!Number.isInteger(parsed) || parsed < 1) {
    throw new Error(`${name} must be a positive integer.`);
  }
  return parsed;
}

function players(prefix) {
  return Array.from({ length: 11 }, (_, index) => `${prefix} Player ${index + 1}`);
}

const north = players('North');
const south = players('South');
const allPlayers = [...north, ...south];
const registry = Object.fromEntries(
  allPlayers.map((name, index) => [name, `fictional-perf-player-${index + 1}`]),
);

function delivery(innings, over, ball) {
  const batting = innings === 0 ? north : south;
  const bowling = innings === 0 ? south : north;
  const striker = batting[(over * 6 + ball) % batting.length];
  const nonStriker = batting[(over * 6 + ball + 1) % batting.length];
  const bowler = bowling[(over + Math.floor(ball / 2)) % bowling.length];
  const runs = (over * 7 + ball * 3 + innings) % 7;

  return {
    batter: striker,
    bowler,
    non_striker: nonStriker,
    runs: { batter: runs, extras: 0, total: runs },
  };
}

function fixture(index) {
  const date = `2025-${String(Math.floor(index / 28) + 1).padStart(2, '0')}-${String((index % 28) + 1).padStart(2, '0')}`;
  const innings = [north, south].map((team, inningsIndex) => ({
    team: inningsIndex === 0 ? 'North XI' : 'South XI',
    overs: Array.from({ length: 20 }, (_, over) => ({
      over,
      deliveries: Array.from({ length: 6 }, (_, ball) => delivery(inningsIndex, over, ball)),
    })),
  }));

  return {
    meta: { data_version: '1.0.0', revision: 1 },
    info: {
      balls_per_over: 6,
      city: 'Fictional City',
      dates: [date],
      event: { name: 'Representative Performance T20', match_number: index + 1 },
      gender: 'male',
      match_type: 'T20',
      outcome: { winner: index % 2 === 0 ? 'North XI' : 'South XI', by: { runs: 12 } },
      overs: 20,
      player_of_match: [north[index % north.length]],
      players: { 'North XI': north, 'South XI': south },
      registry: { people: registry },
      season: '2025/26',
      team_type: 'club',
      teams: ['North XI', 'South XI'],
      toss: { decision: 'bat', winner: index % 2 === 0 ? 'North XI' : 'South XI' },
      venue: 'Representative Ground',
    },
    innings,
  };
}

async function main() {
  const fixtureCount = positiveInteger(
    argument('--fixtures', String(DEFAULT_FIXTURES)),
    '--fixtures',
  );
  const output = resolve(argument('--output', 'data/performance/representative-t20'));
  await mkdir(output, { recursive: true });
  if ((await readdir(output)).length > 0) {
    throw new Error(`Refusing to overwrite non-empty output directory: ${output}`);
  }

  for (let index = 0; index < fixtureCount; index += 1) {
    const filename = `representative-t20-${String(index + 1).padStart(3, '0')}.json`;
    await writeFile(resolve(output, filename), `${JSON.stringify(fixture(index), null, 2)}\n`);
  }

  const manifest = {
    generatedBy: 'scripts/generate-representative-corpus.mjs',
    fictional: true,
    fixtureCount,
    deliveriesPerFixture: DELIVERIES_PER_FIXTURE,
    deliveryCount: fixtureCount * DELIVERIES_PER_FIXTURE,
    sourceReferencePrefix: 'representative-t20-',
  };
  await writeFile(resolve(output, 'manifest.json'), `${JSON.stringify(manifest, null, 2)}\n`);
  console.log(
    `Generated ${fixtureCount} fictional fixtures and ${manifest.deliveryCount} deliveries in ${output}`,
  );
}

main().catch((error) => {
  console.error(error instanceof Error ? error.message : error);
  process.exitCode = 1;
});

/**
 * Measure representative public API reads sequentially and write an auditable
 * Markdown result. The caller supplies IDs from the local synthetic corpus.
 */
import { mkdir, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';

const targets = {
  'public fixture page': 500,
  'fixture event page': 750,
  'fixture statistics': 1500,
  'participant aggregate': 1500,
  'CSV event export': 1000,
};

function value(name, environmentName) {
  const index = process.argv.indexOf(name);
  return index === -1 ? process.env[environmentName] : process.argv[index + 1];
}

function positiveInteger(value, name) {
  const parsed = Number(value);
  if (!Number.isInteger(parsed) || parsed < 1)
    throw new Error(`${name} must be a positive integer.`);
  return parsed;
}

function percentile(samples, fraction) {
  const ordered = [...samples].sort((left, right) => left - right);
  return ordered[Math.ceil(ordered.length * fraction) - 1];
}

async function request(url) {
  const started = process.hrtime.bigint();
  const response = await fetch(url, { headers: { accept: 'application/json,text/csv;q=0.9' } });
  await response.arrayBuffer();
  const elapsed = Number(process.hrtime.bigint() - started) / 1_000_000;
  if (!response.ok) throw new Error(`${response.status} ${response.statusText} for ${url}`);
  return elapsed;
}

async function main() {
  const baseUrl = value('--base-url', 'PERF_BASE_URL')?.replace(/\/$/, '');
  const fixtureId = value('--fixture-id', 'PERF_FIXTURE_ID');
  const participantId = value('--participant-id', 'PERF_PARTICIPANT_ID');
  const output = resolve(
    value('--output', 'PERF_OUTPUT') ?? 'evidence/validation/issue-289-local-measurement.md',
  );
  const samples = positiveInteger(value('--samples', 'PERF_SAMPLES') ?? '10', '--samples');
  if (!baseUrl || !fixtureId || !participantId) {
    throw new Error(
      'Set --base-url, --fixture-id and --participant-id (or PERF_BASE_URL, PERF_FIXTURE_ID and PERF_PARTICIPANT_ID).',
    );
  }

  const operations = {
    'public fixture page': `${baseUrl}/api/v1/fixtures?limit=50`,
    'fixture event page': `${baseUrl}/api/v1/fixtures/${fixtureId}/events?limit=100`,
    'fixture statistics': `${baseUrl}/api/v1/fixtures/${fixtureId}/statistics`,
    'participant aggregate': `${baseUrl}/api/v1/participants/${participantId}/statistics`,
    'CSV event export': `${baseUrl}/api/v1/fixtures/${fixtureId}/events/export.csv`,
  };

  // This discarded request establishes the retained database-pool client. It is
  // required for a warm run and intentionally not included in any percentile.
  await request(`${baseUrl}/api/v1/competitions?limit=1`);
  const results = [];
  for (const [name, url] of Object.entries(operations)) {
    const timings = [];
    for (let index = 0; index < samples; index += 1) timings.push(await request(url));
    const p95 = percentile(timings, 0.95);
    results.push({
      name,
      p50: percentile(timings, 0.5),
      p95,
      target: targets[name],
      passed: p95 <= targets[name],
    });
  }

  const lines = [
    '# Issue #289 local representative-scale measurement',
    '',
    `- Base URL: ${baseUrl}`,
    `- Fixture ID: ${fixtureId}; participant ID: ${participantId}`,
    `- Samples per operation: ${samples}; sequential warm-cache requests`,
    '- Warm-up: one successful database-backed request discarded before sampling.',
    '',
    '| Operation | P50 (ms) | P95 (ms) | Target (ms) | Result |',
    '| --- | ---: | ---: | ---: | --- |',
    ...results.map(
      (result) =>
        `| ${result.name} | ${result.p50.toFixed(1)} | ${result.p95.toFixed(1)} | ${result.target} | ${result.passed ? 'pass' : 'fail'} |`,
    ),
    '',
    'This run uses no credentials, private data or production endpoint. See docs/development/performance-baseline.md for setup and cold-run procedure.',
    '',
  ];
  await mkdir(dirname(output), { recursive: true });
  await writeFile(output, lines.join('\n'));
  console.log(`Wrote ${output}`);
  if (results.some((result) => !result.passed)) process.exitCode = 2;
}

main().catch((error) => {
  console.error(error instanceof Error ? error.message : error);
  process.exitCode = 1;
});

import { pathToFileURL } from 'node:url';

const DEFAULT_ATTEMPTS = 12;
const DEFAULT_DELAY_MS = 10_000;
const DEFAULT_TIMEOUT_MS = 10_000;
const MAX_ERROR_BODY_LENGTH = 500;

function readPositiveInteger(value, fallback, name) {
  if (value === undefined) {
    return fallback;
  }

  const parsedValue = Number(value);

  if (!Number.isInteger(parsedValue) || parsedValue <= 0) {
    throw new Error(`${name} must be a positive integer.`);
  }

  return parsedValue;
}

function sleep(delayMs) {
  return new Promise((resolve) => setTimeout(resolve, delayMs));
}

function describeResponseFailure(response, body, expectedText) {
  if (!response.ok) {
    const bodySummary = body.trim().slice(0, MAX_ERROR_BODY_LENGTH);
    const suffix = bodySummary ? ` Response: ${bodySummary}` : '';
    return `HTTP ${response.status}.${suffix}`;
  }

  return `response did not contain ${JSON.stringify(expectedText)}.`;
}

export async function smokeCheck(
  {
    label,
    url,
    expectedText,
    attempts = DEFAULT_ATTEMPTS,
    delayMs = DEFAULT_DELAY_MS,
    timeoutMs = DEFAULT_TIMEOUT_MS,
  },
  dependencies = {},
) {
  if (!label?.trim()) {
    throw new Error('Smoke-check label is required.');
  }

  let targetUrl;

  try {
    targetUrl = new URL(url);
  } catch {
    throw new Error(`Smoke-check URL is invalid: ${url}`);
  }

  if (!['http:', 'https:'].includes(targetUrl.protocol)) {
    throw new Error('Smoke-check URL must use HTTP or HTTPS.');
  }

  const fetchRequest = dependencies.fetchRequest ?? globalThis.fetch;
  const wait = dependencies.wait ?? sleep;
  const logger = dependencies.logger ?? console;

  for (let attempt = 1; attempt <= attempts; attempt += 1) {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), timeoutMs);

    try {
      const response = await fetchRequest(targetUrl, {
        headers: { Accept: '*/*' },
        redirect: 'follow',
        signal: controller.signal,
      });
      const body = await response.text();
      const hasExpectedText = expectedText === undefined || body.includes(expectedText);

      if (response.ok && hasExpectedText) {
        logger.log(
          `[smoke] ${label} passed on attempt ${attempt}/${attempts} (HTTP ${response.status}).`,
        );
        return { attempts: attempt, status: response.status };
      }

      throw new Error(describeResponseFailure(response, body, expectedText));
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      logger.error(`[smoke] ${label} attempt ${attempt}/${attempts} failed: ${message}`);

      if (attempt === attempts) {
        throw new Error(`${label} failed after ${attempts} attempts. Last error: ${message}`);
      }
    } finally {
      clearTimeout(timeout);
    }

    await wait(delayMs);
  }

  throw new Error(`${label} failed without making a request.`);
}

async function runFromCommandLine() {
  const [label, url, expectedText] = process.argv.slice(2);

  if (!label || !url) {
    console.error(
      'Usage: node scripts/smoke-check-deployment.mjs <label> <url> [expected-response-text]',
    );
    process.exitCode = 2;
    return;
  }

  try {
    await smokeCheck({
      label,
      url,
      expectedText,
      attempts: readPositiveInteger(
        process.env.SMOKE_CHECK_ATTEMPTS,
        DEFAULT_ATTEMPTS,
        'SMOKE_CHECK_ATTEMPTS',
      ),
      delayMs: readPositiveInteger(
        process.env.SMOKE_CHECK_DELAY_MS,
        DEFAULT_DELAY_MS,
        'SMOKE_CHECK_DELAY_MS',
      ),
      timeoutMs: readPositiveInteger(
        process.env.SMOKE_CHECK_TIMEOUT_MS,
        DEFAULT_TIMEOUT_MS,
        'SMOKE_CHECK_TIMEOUT_MS',
      ),
    });
  } catch (error) {
    console.error(`[smoke] ${error instanceof Error ? error.message : String(error)}`);
    process.exitCode = 1;
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  await runFromCommandLine();
}

# Issue #540 â€” Season-scale asynchronous publication acceptance

## Purpose

This evidence records the deployed acceptance and recovery testing for Issue #540, which addressed synchronous season-scale publication inside the reviewer request, stranded `publishing` batches, misleading review failures, and publication throughput above the required acceptance target.

## Original failure

The original representative season-scale batch was:

`486d496e-8abd-47d7-9988-cebd8fd01095`

The batch had already received an `approved` review decision but remained in `publishing` after the original synchronous publication attempt.

Before recovery:

- batch state: `publishing`
- no durable `batch.publish` background job existed
- 15,530 accepted items remained
- 402 items had already reached `duplicate_skipped`
- 781 items were rejected

This demonstrated that publication had partially executed before the request/process failed and that the remaining work had been stranded.

## Durable recovery acceptance

After the asynchronous publication fix was deployed, the existing approved decision was replayed idempotently.

A single durable publication job was created:

`d6ca321c-d52d-48a4-8261-eaa5bfb56018`

Observed final job state:

- job state: `succeeded`
- attempt count: `4`
- progress: `15,530 / 15,530`
- publication jobs created for the batch: `1`

The duplicate approval replay did not create a second publication job.

Final batch state:

`published`

Final item states:

- `duplicate_skipped`: 15,932
- `rejected`: 781
- `accepted`: 0

This demonstrates that the stranded batch resumed through the durable worker path and ultimately completed rather than restarting or remaining indefinitely in `publishing`.

## Publication throughput investigation

The recovered batch demonstrated that durability and retry/resume behaviour worked, but publication still exceeded the season-scale performance target.

Runtime investigation showed that duplicate and published-conflict outcomes were being persisted using sequential per-item database operations inside each publication chunk.

For an exact duplicate, the publication path performed:

1. an individual `batch_item` update; and
2. an individual `batch_validation_result` insert.

With hundreds of duplicate items per chunk, this produced an N+1 database round-trip pattern.

A regression test was added before the optimisation.

Before the fix:

- 3 exact duplicates produced 3 duplicate persistence statements;
- 3 published conflicts produced 3 conflict persistence statements.

The publication engine was then changed to accumulate duplicate and conflict classifications for the chunk and persist each outcome class using a set-based PostgreSQL statement with `jsonb_to_recordset`.

After the fix:

- exact duplicate outcome persistence is set-based per chunk;
- published-conflict outcome persistence is set-based per chunk;
- existing new-delivery bulk publication remains unchanged;
- checkpoint, lease, retry and resume semantics remain unchanged.

Focused throughput regression tests passed after the change.

The full worker suite passed with:

`63 / 63 tests`

The shared `@sport-analytics/batch-processing` package built successfully and full local CI passed.

## Final deployed season-scale acceptance

The final acceptance batch was:

`a8718ca6-848e-4e06-b07b-fc7a67ee670c`

Source package:

`issue-540-throughput-replay.json`

The package was a byte-different replay of the previously validated IPL 2013 season-scale package so that the same representative workload could be exercised without reusing the previous upload receipt.

Validation/review state before approval:

- total events: 16,713
- accepted: 15,932
- rejected: 781
- blocking errors: 0
- unresolved references: 0
- published conflicts after resolution: 0
- duplicate resolutions before publication: 2
- state: `awaiting_review`

The two published-delivery conflicts were reviewed using the existing canonical published deliveries. No submitted correction was applied.

## Final publication result

The durable publication job was:

`49144373-b401-467d-9bcc-c97c65216f3f`

Observed final job state:

- job state: `succeeded`
- attempt count: `1`
- worker progress: `15,930 / 15,930`

The worker progress total was 15,930 because two items had already been resolved as duplicate outcomes before publication began.

Final batch state:

`published`

Final item states:

- `duplicate_skipped`: 15,932
- `rejected`: 781
- `accepted`: 0

No accepted records remained stranded after publication.

## Performance result

Acceptance timer start:

`2026-09-15T09:40:16.9410651+02:00`

Completion observed:

`2026-09-15T09:43:54.1767767+02:00`

Elapsed:

