import {
  createDatasetReleaseSchema,
  datasetReleaseVersionSchema,
} from '@sport-analytics/contracts';
import { Router } from 'express';
import { pipeline } from 'node:stream';
import { z } from 'zod';

import type { VerifyAccessToken } from '../../auth/supabase-auth';
import { requireAuthentication } from '../../middleware/require-authentication';
import { requireAdministrator } from '../../middleware/require-authorization';
import type { SynchronizeAccount } from '../accounts/account.service';
import type { DatasetReleaseService } from './dataset-release.service';

export function createDatasetReleaseRouter(
  verifyAccessToken: VerifyAccessToken,
  synchronizeAccount: SynchronizeAccount,
  service: DatasetReleaseService,
): Router {
  const router = Router();
  const authenticate = requireAuthentication(verifyAccessToken, synchronizeAccount);

  router.post(
    '/admin/dataset-releases',
    authenticate,
    requireAdministrator(),
    (request, response, next) => {
      const parsed = createDatasetReleaseSchema.safeParse(request.body);
      if (!parsed.success) {
        response
          .status(400)
          .json({ error: { code: 'VALIDATION_FAILED', message: 'The request is invalid.' } });
        return;
      }
      const account = response.locals.authenticatedAccount as { accountId: string };
      void service
        .requestRelease(parsed.data, account.accountId)
        .then((result) => {
          if (result.release) {
            response.status(200).json({ data: result.release });
            return;
          }
          response.status(202).json({ data: result.job });
        })
        .catch(next);
    },
  );

  router.get(
    '/admin/dataset-release-jobs/:jobId',
    authenticate,
    requireAdministrator(),
    (request, response, next) => {
      const jobId = z.string().uuid().safeParse(request.params.jobId);
      if (!jobId.success) {
        response
          .status(404)
          .json({ error: { code: 'NOT_FOUND', message: 'Dataset release job not found.' } });
        return;
      }
      void service
        .getJob(jobId.data)
        .then((job) => {
          if (!job) {
            response
              .status(404)
              .json({ error: { code: 'NOT_FOUND', message: 'Dataset release job not found.' } });
            return;
          }
          response.status(200).json({ data: job });
        })
        .catch(next);
    },
  );

  router.get('/dataset-releases', (_request, response, next) => {
    void service
      .listReleases()
      .then((releases) => response.status(200).json({ data: releases }))
      .catch(next);
  });

  router.get('/dataset-releases/:version', (request, response, next) => {
    const version = datasetReleaseVersionSchema.safeParse(request.params.version);
    if (!version.success) {
      response
        .status(404)
        .json({ error: { code: 'NOT_FOUND', message: 'Dataset release not found.' } });
      return;
    }
    void service
      .getRelease(version.data)
      .then((release) => {
        if (!release) {
          response
            .status(404)
            .json({ error: { code: 'NOT_FOUND', message: 'Dataset release not found.' } });
          return;
        }
        response.status(200).json({ data: release });
      })
      .catch(next);
  });

  router.get('/dataset-releases/:version/artifact.json', (request, response, next) => {
    const version = datasetReleaseVersionSchema.safeParse(request.params.version);
    if (!version.success) {
      response
        .status(404)
        .json({ error: { code: 'NOT_FOUND', message: 'Dataset release artifact not found.' } });
      return;
    }
    void service
      .getArtifact(version.data)
      .then((artifact) => {
        if (!artifact) {
          response
            .status(404)
            .json({ error: { code: 'NOT_FOUND', message: 'Dataset release artifact not found.' } });
          return;
        }
        response.type('application/json').attachment(`dataset-release-${version.data}.json`);
        pipeline(artifact, response, (error) => {
          if (error) {
            next(error);
          }
        });
      })
      .catch(next);
  });

  return router;
}

import { Readable } from 'node:stream';

import {
  DATASET_RELEASE_FORMAT_VERSION,
  DATASET_RELEASE_FIELDS,
  DATASET_RELEASE_SCOPE,
  type CreateDatasetRelease,
  type DatasetRelease,
  type DatasetReleaseJob,
} from '@sport-analytics/contracts';

import { ObjectStorageError, type ObjectStore } from '../object-storage/object-store';
import {
  createDatasetReleaseRepository,
  type DatasetReleaseJobRecord,
  type DatasetReleaseRepository,
  type DatasetReleaseSnapshot,
} from './dataset-release.repository';

interface DatasetReleaseRequestResult {
  release: DatasetRelease | null;
  job: DatasetReleaseJob | null;
}

function toApiDateTime(value: string): string {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new TypeError('Dataset release timestamp is invalid.');
  }
  return date.toISOString();
}

function toNullableApiDateTime(value: string | null): string | null {
  return value === null ? null : toApiDateTime(value);
}

export interface DatasetReleaseService {
  requestRelease(
    input: CreateDatasetRelease,
    requesterId: string,
  ): Promise<DatasetReleaseRequestResult>;
  getJob(jobId: string): Promise<DatasetReleaseJob | null>;
  listReleases(): Promise<DatasetRelease[]>;
  getRelease(version: string): Promise<DatasetRelease | null>;
  getArtifact(version: string): Promise<Readable | null>;
}

export interface DatasetReleaseServiceOptions {
  deploymentEnvironment: string;
  storageProvider?: 'azure' | 'filesystem' | undefined;
  releaseObjectStore?: ObjectStore | undefined;
  legacyObjectStore?: ObjectStore | undefined;
}

function mapSnapshot(snapshot: DatasetReleaseSnapshot): DatasetRelease {
  return {
    releaseId: snapshot.releaseId,
    version: snapshot.version,
    createdAt: toApiDateTime(snapshot.createdAt),
    snapshotId: snapshot.snapshotId,
    snapshotAsOf: toNullableApiDateTime(snapshot.snapshotAsOf),
    formatVersion: DATASET_RELEASE_FORMAT_VERSION,
    scope: DATASET_RELEASE_SCOPE,
    eventCount: snapshot.eventCount,
    checksum: snapshot.checksum,
    fields: [...DATASET_RELEASE_FIELDS],
  };
}

function mapJob(job: DatasetReleaseJobRecord): DatasetReleaseJob {
  const status =
    job.state === 'queued'
      ? 'pending'
      : job.state === 'running'
        ? 'generating'
        : job.state === 'succeeded'
          ? 'completed'
          : 'failed';
  return {
    jobId: job.jobId,
    version: job.version,
    status,
    eventsProcessed: job.eventsProcessed,
    bytesWritten: job.bytesWritten,
    pageNumber: job.pageNumber,
    createdAt: toApiDateTime(job.createdAt),
    startedAt: toNullableApiDateTime(job.startedAt),
    completedAt: toNullableApiDateTime(job.completedAt),
    failureCode: job.failureCode,
    failureMessage: job.failureMessage,
    release: job.release ? mapSnapshot(job.release) : null,
  };
}

export function createDatasetReleaseService(
  repository: DatasetReleaseRepository = createDatasetReleaseRepository(),
  options: DatasetReleaseServiceOptions,
): DatasetReleaseService {
  return {
    async requestRelease(input, requesterId) {
      if (!options.storageProvider || !options.releaseObjectStore) {
        throw new ObjectStorageError('Dataset release object storage is not configured.');
      }
      const result = await repository.requestGeneration({
        version: input.version,
        requesterId,
        deploymentEnvironment: options.deploymentEnvironment,
        storageProvider: options.storageProvider,
      });
      return {
        release: result.release ? mapSnapshot(result.release) : null,
        job: result.job ? mapJob(result.job) : null,
      };
    },
    async getJob(jobId) {
      const job = await repository.findJob(jobId, options.deploymentEnvironment);
      return job ? mapJob(job) : null;
    },
    async listReleases() {
      return (await repository.list(options.deploymentEnvironment)).map(mapSnapshot);
    },
    async getRelease(version) {
      const release = await repository.findByVersion(version, options.deploymentEnvironment);
      return release ? mapSnapshot(release) : null;
    },
    async getArtifact(version) {
      const reference = await repository.findArtifactReferenceByVersion(
        version,
        options.deploymentEnvironment,
      );
      if (!reference) return null;
      if (reference.storageKey) {
        const store =
          reference.storageLocation === 'release'
            ? options.releaseObjectStore
            : options.legacyObjectStore;
        if (!store)
          throw new ObjectStorageError('Dataset release object storage is not configured.');
        return store.read(reference.storageKey);
      }
      return reference.legacyArtifactText === null
        ? null
        : Readable.from(Buffer.from(reference.legacyArtifactText));
    },
  };
}

# Azure asynchronous batch worker

Issue #365 provisions the deployment target selected by accepted ADR-010. The target is a Node.js 22
Azure Container App, separate from the Express App Service, consuming Azure Service Bus Standard in
peek-lock mode. Supabase PostgreSQL remains authoritative and staged bytes remain in a private Azure
Blob container. Issue #278 adds the transactional outbox relay and the `batch.validate` version 1
handler for package expansion, reference resolution, bounded validation chunks and durable resume.
The existing read-only `worker.probe` version 1 command remains available for deployment checks.

## Provisioned boundary

`infra/azure/worker/main.bicep` creates worker-owned resources idempotently:

- a Container Apps environment and private-ingress Container App;
- a Standard Service Bus namespace and `batch-ingestion` queue;
- one-minute peek locks, duplicate detection, five deliveries and a dead-letter queue;
- a Basic private Azure Container Registry;
- separate runtime and image-pull managed identities;
- least-privilege queue receiver and sender, Blob contributor, Key Vault secret-reader and ACR pull roles;
- startup, liveness and dependency-aware readiness probes;
- one to three replicas with a managed-identity Service Bus KEDA rule; and
- a 30-day Log Analytics workspace for JSON console logs.

The template references the existing storage account/container and an existing Key Vault. It never
receives a database password as a command-line parameter: `DATABASE_URL` is a Key Vault reference in
the Container App, while Azure data-plane clients use `DefaultAzureCredential` and the dedicated
managed identity. Ingress is internal because worker health is an operator surface, not a public API.

## Runtime configuration

| Variable                                 | Secret | Purpose                                                                           |
| ---------------------------------------- | ------ | --------------------------------------------------------------------------------- |
| `DATABASE_URL`                           | Yes    | Supabase PostgreSQL session-pooler URL, supplied through Key Vault.               |
| `DATABASE_SSL_MODE`                      | No     | Must be `verify-full` in production; local PostgreSQL may use `disable`.          |
| `DATABASE_CA_CERT_PATH`                  | No     | Optional CA override; the image includes the Supabase root CA.                    |
| `SERVICE_BUS_FULLY_QUALIFIED_NAMESPACE`  | No     | `<namespace>.servicebus.windows.net`.                                             |
| `SERVICE_BUS_QUEUE_NAME`                 | No     | Dedicated queue name, normally `batch-ingestion`.                                 |
| `AZURE_STORAGE_ACCOUNT_NAME`             | No     | Existing Blob account containing staged payloads.                                 |
| `AZURE_STORAGE_CONTAINER_NAME`           | No     | Existing private container, normally `staged-ingestion`.                          |
| `AZURE_STORAGE_INGESTION_CONTAINER_NAME` | No     | Preferred explicit staged-ingestion container; old name remains an alias.         |
| `AZURE_STORAGE_RELEASE_CONTAINER_NAME`   | No     | Existing private immutable-release container, normally `dataset-releases`.        |
| `OBJECT_STORAGE_PROVIDER`                | No     | `azure` in production; filesystem is rejected there.                              |
| `WORKER_TRANSPORT_PROVIDER`              | No     | `azure-service-bus` in production; `database` supports local work without Azure.  |
| `DEPLOYMENT_ENVIRONMENT`                 | No     | Stable namespace shared with the backend, normally `dev`.                         |
| `AZURE_CLIENT_ID`                        | No     | User-assigned runtime identity client ID.                                         |
| `WORKER_PORT`                            | No     | Internal health port; default `3001`.                                             |
| `WORKER_CONCURRENCY`                     | No     | Per-replica Service Bus concurrency, bounded to 1â€“16; deployed value is 1.        |
| `SERVICE_BUS_LOCK_RENEWAL_MS`            | No     | Automatic peek-lock renewal window; deployed value is four minutes.               |
| `WORKER_SHUTDOWN_TIMEOUT_MS`             | No     | Drain deadline; deployed value is 25 seconds within the 30-second platform grace. |
| `WORKER_PROBE_DELAY_MS`                  | No     | Recovery-test-only delay; keep `0` normally.                                      |
| `OUTBOX_POLL_INTERVAL_MS`                | No     | Empty-poll delay for the transactional outbox relay; default `1000`.              |
| `OUTBOX_CLAIM_TTL_MS`                    | No     | PostgreSQL claim lease for an outbox publish attempt; default `30000`.            |
| `OUTBOX_BATCH_SIZE`                      | No     | Maximum outbox rows claimed in one set-based poll; default `20`.                  |
| `BATCH_CHUNK_SIZE`                       | No     | Maximum staged items persisted per validation transaction; default `500`.         |
| `BATCH_LEASE_MS`                         | No     | Durable validation lease before another worker may reclaim the batch; `120000`.   |
| `LOG_LEVEL`                              | No     | `debug`, `info`, `warn` or `error`.                                               |

Do not create Service Bus connection strings, storage keys or SAS tokens for the worker. Do not use
`VITE_` variables: every value above is server-side.

## Local execution and recovery walkthrough

### Prerequisites

Install Node.js 22, npm 10, Docker Desktop, and Azure CLI. The Azure account used locally must be
granted Service Bus Data Receiver on the test queue and Blob Data Reader (or Contributor) on the test
container. To enqueue probes it also needs Service Bus Data Sender. Use only a development resource
group and an isolated local database.

1. Install dependencies and start PostgreSQL from the repository root:

   ```powershell
   npm.cmd ci
   docker compose -f compose.test.yml up -d --wait
   ```

   Expected: Docker reports `postgres-test` healthy on `127.0.0.1:55432`.

2. Reset, migrate and seed only the disposable database:

   ```powershell
   $env:NODE_ENV = 'test'
   $env:DATABASE_URL_TEST = 'postgresql://test_user:test_password@127.0.0.1:55432/sport_analytics_test'
   $env:SUPABASE_URL = 'https://example.invalid'
   $env:SUPABASE_PUBLISHABLE_KEY = 'test-publishable-key'
   npm.cmd run db:test:reset --workspace=@sport-analytics/backend
   npm.cmd run db:test:migrate --workspace=@sport-analytics/backend
   npm.cmd run db:test:seed --workspace=@sport-analytics/backend
   ```

   Expected: all three commands exit zero. The safety guard rejects a non-test database name or a
   URL equal to `DATABASE_URL`.

3. Sign in and select the approved development subscription:

   ```powershell
   az login
   az account set --subscription '<development-subscription-id>'
   ```

   Expected: `az account show` identifies the intended development subscription. Never use a
   production subscription for the interruption exercise.

